css:
.d1126-box,.d1126-bar,.d1126-arr{transform-box:fill-box}
.d1126-box{animation:d1126-a 3.4s ease-in-out infinite}
.d1126-bar{transform-origin:50% 100%;animation:d1126-b 3.6s ease-in-out infinite}
.d1126-arr{animation:d1126-c 3.6s ease-in-out infinite}
@keyframes d1126-a{0%,15%{transform:translateX(0)}60%,100%{transform:translateX(50px)}}
@keyframes d1126-b{0%,15%{transform:scaleY(1)}70%,100%{transform:scaleY(.4)}}
@keyframes d1126-c{0%,15%{transform:translateY(0)}70%,100%{transform:translateY(25px)}}
@media (prefers-reduced-motion:reduce){.d1126-box{transform:translateX(50px)}.d1126-bar{transform:scaleY(.4)}.d1126-arr{transform:translateY(25px)}}
